def check_condition(K, M=2021):
    """
    Checks if the set K satisfies the condition:
    For all p, q in K, there exists r in K such that p+q-2r is a multiple of M.
    Equivalent to checking if 1011*(p+q) mod M is in K, where 1011 = 2^{-1} mod 2021.
    """
    INV2 = 1011
    for p in K:
        for q in K:
            sum_pq = (p + q) % M
            r_candidate = (INV2 * sum_pq) % M
            if r_candidate not in K:
                return False
    return True

# --- Test |K|=3 ---
# Testing small sets containing 0, as derived from structural analysis hints.
test_k3 = []
k_elements_small = list(range(15))

# Test {0, 1, k3}
for k3 in k_elements_small[1:]:
    K = {0, 1, k3}
    if check_condition(K):
        test_k3.append(K)

# Test {0, 2, k3}
for k3 in k_elements_small[1:]:
    if k3 not in {0, 2}:
        K = {0, 2, k3}
        if check_condition(K):
            test_k3.append(K)

print(f"Found |K|=3 examples: {test_k3}")

