test_k4 = []
# Testing small sets containing 0
for k1 in range(1, 8):
    for k2 in range(k1 + 1, 8):
        for k3 in range(k2 + 1, 8):
            K = {0, k1, k2, k3}
            if check_condition(K):
                test_k4.append(K)

print(f"Found |K|=4 examples: {test_k4}")
